// Des: Tests for chat read: name parse, overlap diff, unread
// Flo: pure helpers > mock page read twice > only new messages saved
// I/O: strings and html > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const lab = @import("cf-labl-load.zig"); const rd = @import("ru-chat-read.zig"); const sess = @import("ru-sess-ctxz.zig"); const data = @import("st-stat-data.zig"); const conf = @import("cf-conf-load.zig"); const mock = @import("te-mock-page.zig"); const snap = @import("ru-page-snap.zig"); const fixt = @import("te-fixt-html.zig"); const T = std.testing;
const NOON: i64 = 100 * 86400000 + 12 * 3600000;
fn profOf(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}/prof", .{tmpz.sub_path}); }
fn msg(who: []const u8, body: []const u8) data.Msgz { return .{ .who = who, .body = body, .ts = 0 }; }
test "overlap diff: empty tail, full overlap, partial, none" { const one = [_]data.Msgz{ msg("them", "a"), msg("me", "b") }; try T.expectEqual(@as(usize, 2), rd.newSince(&.{}, &one).len); try T.expectEqual(@as(usize, 0), rd.newSince(&one, &one).len); const more = [_]data.Msgz{ msg("them", "a"), msg("me", "b"), msg("them", "c") }; const nw = rd.newSince(&one, &more); try T.expectEqual(@as(usize, 1), nw.len); try T.expectEqualStrings("c", nw[0].body); const win = [_]data.Msgz{ msg("me", "b"), msg("them", "c"), msg("them", "d") }; try T.expectEqualStrings("d", rd.newSince(&one, &win)[1].body); const other = [_]data.Msgz{ msg("them", "x") }; try T.expectEqual(@as(usize, 1), rd.newSince(&one, &other).len); }
test "overlap diff keeps repeated identical messages" { const tail = [_]data.Msgz{msg("them", "ok")}; const shot = [_]data.Msgz{ msg("them", "ok"), msg("them", "ok") }; try T.expectEqual(@as(usize, 1), rd.newSince(&tail, &shot).len); try T.expectEqual(@as(usize, 0), rd.newSince(&shot, &shot).len); }
test "M5 live: read unread chats, second read saves nothing, new message is picked up" { const gpa = T.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var mok = try mock.start(gpa, T.io, try profOf(&tmpz, &buff), fixt.chat); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); var sto = try data.Stor.open(gpa, ":memory:"); defer sto.close(); var cfg: conf.Conf = .{}; cfg.type_dely_msec = .{ 1, 2 }; cfg.warm_dayz_coun = 0; var ses = sess.Sess.init(gpa, T.io, aren.allocator(), cfg, &sto, mok.conn, .read); ses.fast = true; ses.fake_ms = NOON; ses.job = "read"; const chats = try rd.listChats(&ses); try T.expectEqual(@as(usize, 2), chats.len); try T.expect(chats[0].unre and !chats[1].unre); const sum = try rd.readUnread(&ses); try T.expectEqual(@as(u32, 1), sum.chats); try T.expectEqual(@as(u32, 2), sum.newm); const again = try rd.readChat(&ses, "Mom"); try T.expectEqual(@as(u32, 0), again); _ = try snap.evalStr(aren.allocator(), mok.conn, "D.Mom.push('them|new one')"); try T.expectEqual(@as(u32, 1), try rd.readChat(&ses, "mom")); const tail = try sto.msgTail(aren.allocator(), "Mom", 10); try T.expectEqual(@as(usize, 3), tail.len); try T.expectEqualStrings("Dinner at 7?", tail[1].body); try T.expectEqualStrings("them", tail[2].who); }
test "live: unknown chat is NoElem and logged, sent nothing" { const gpa = T.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var mok = try mock.start(gpa, T.io, try profOf(&tmpz, &buff), fixt.chat); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); var sto = try data.Stor.open(gpa, ":memory:"); defer sto.close(); var cfg: conf.Conf = .{}; cfg.warm_dayz_coun = 0; var ses = sess.Sess.init(gpa, T.io, aren.allocator(), cfg, &sto, mok.conn, .read); ses.fast = true; ses.fake_ms = NOON; ses.job = "read"; try T.expectError(error.NoElem, rd.readChat(&ses, "Nobody")); const rows = try sto.logTail(aren.allocator(), 5); try T.expect(rows.len >= 1); try T.expectEqualStrings("warn", rows[rows.len - 1].lvl); }
test "quiet hours stop even a read" { const gpa = T.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var mok = try mock.start(gpa, T.io, try profOf(&tmpz, &buff), fixt.chat); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); var sto = try data.Stor.open(gpa, ":memory:"); defer sto.close(); var cfg: conf.Conf = .{}; cfg.loca_utcz_mins = 0; var ses = sess.Sess.init(gpa, T.io, aren.allocator(), cfg, &sto, mok.conn, .read); ses.fast = true; ses.fake_ms = 100 * 86400000 + 2 * 3600000; try T.expectError(error.QuietHrs, rd.readChat(&ses, "Mom")); }
test "chat name strips unread and stranger marks in both languages" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const reg = try lab.builtin(aren.allocator()); try T.expectEqualStrings("Mom", rd.chatName(&reg, "Mom unread 2")); try T.expectEqualStrings("Boss", rd.chatName(&reg, "Boss")); try T.expectEqualStrings("Zed", rd.chatName(&reg, "Zed - người lạ")); try T.expectEqualStrings("Zed", rd.chatName(&reg, "Zed - stranger")); try T.expectEqualStrings("Lan", rd.chatName(&reg, "Lan chưa đọc 3")); try T.expect(rd.isUnread(&reg, "Mom Unread 2")); try T.expect(rd.isUnread(&reg, "Lan chưa đọc")); try T.expect(!rd.isUnread(&reg, "Boss")); try T.expect(rd.isStranger(&reg, "Zed - stranger")); try T.expect(!rd.isStranger(&reg, "Zedd")); }
